  boolean dynamicRefused=false;try{var advancing=new NativeRampFramePublisher.Frame(oldCells,new NativeRampPartData.Motion(0,world.getGameTime(),0,1,8,true,0),NativeRampPartData.Belt.NONE,0);NativeRampFramePublisher.prepare(world,block,operation.id(),ROOT,assembly,advancing,after,2);}catch(IllegalArgumentException expected){dynamicRefused=true;}need(dynamicRefused,"rollback controls must be caller-frozen");
