  next=NativeRampFramePublisher.prepare(world,block,operation.id(),ROOT,assembly,before,after,2);net.minecraft.world.entity.animal.Pig pig=null;NativeRampRiderPlan riderPlan=null;net.minecraft.world.phys.Vec3 pigPosition=null;if(mode.startsWith("frame-rider-")){pig=new net.minecraft.world.entity.animal.Pig(net.minecraft.world.entity.EntityType.PIG,world);pig.setNoGravity(true);pig.setPos(A.getX()+.5,A.getY()+.5,A.getZ()+.5);pig.setOnGround(true);pig.setDeltaMovement(net.minecraft.world.phys.Vec3.ZERO);need(world.addFreshEntity(pig),"actual rider installed");pigPosition=pig.position();riderPlan=NativeRampRiderPlan.prepare(world,assembly.footprint(),false,0,1,false,false);need(riderPlan!=null&&riderPlan.size()==1&&riderPlan.recheck(),"actual one-rider frame preflight");}boolean failing=mode.contains("failure");if(failing)NativeRampFramePublisher.testFault=stage->{if(stage.equals(mode.startsWith("frame-retire")?"after-retirement":"after-candidate"))throw new IllegalStateException("fixture prepared frame failure "+stage);};NativeRampFramePublisher.Result result;try(var scope=NativeRampHeldOwners.mutate(operation)){result=next.install();}finally{NativeRampFramePublisher.testFault=null;}
