   need(riderPlan.recheck()&&riderPlan.commit((p,payload)->{throw new AssertionError("Unexpected player");}),"actual rider commits after candidate");next.complete();need(!pig.position().equals(pigPosition),"actual rider moved with current prepared endpoint");observedCells=newCells;observing=true;throwObserver=true;boolean observerFailed=false;try{((NativeRampPartEntity)world.getBlockEntity(newCells.iterator().next())).setChanged();}catch(IllegalStateException expectedFailure){observerFailed=true;}finally{observing=false;throwObserver=false;observedCells=Set.of(A,B);}need(observerFailed&&!next.pendingRollback(),"post-actor observer failure cannot trigger implicit rollback");for(var pos:newCells)need(world.getBlockEntity(pos) instanceof NativeRampPartEntity part&&part.publication().pose()==1,"committed endpoint retained after observer failure");
   var returning=NativeRampRiderPlan.prepare(world,assembly.footprint(),false,1,0,false,false);need(returning!=null&&returning.size()==1,"actual inverse rider return prepared before original recovery");var home=new NativeRampFramePublisher.Frame(oldCells,new NativeRampPartData.Motion(2,world.getGameTime(),0,0,8,false,0),NativeRampPartData.Belt.NONE,3);try(var reset=NativeRampFramePublisher.prepare(world,block,operation.id(),ROOT,assembly,after,home,4)){try(var scope=NativeRampHeldOwners.mutate(operation)){need(reset.install().status()==NativeRampFramePublisher.Status.INSTALLED,"inverse generated frame installed");need(returning.recheck()&&returning.commit((p,payload)->{throw new AssertionError("Unexpected player");}),"actual inverse riders committed");}reset.complete();}need(pig.position().distanceToSqr(pigPosition)<1e-18,"actor returns before journal original restoration");pig.discard();returned=true;
